```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream f1("uczniowie.txt");
    map<int, string> uczniowie;
    int id; string imie;
    while (f1 >> id >> imie) uczniowie[id] = imie;
    ifstream f2("oceny.txt");
    string przedmiot;
    int ocena;
    map<int, pair<int,int>> dane;
    while (f2 >> id >> przedmiot >> ocena) {
        dane[id].first += ocena;
        dane[id].second++;
    }
    cout << fixed << setprecision(2);
    cout << "Srednie ocen:" << endl;
    string bestP, worstP;
    double bestA = -1, worstA = 100;
    for (auto& p : dane) {
        double avg = (double)p.second.first / p.second.second;
        cout << "   " << uczniowie[p.first] << ": " << avg << endl;
        if (avg > bestA) { bestA = avg; bestP = uczniowie[p.first]; }
        if (avg < worstA) { worstA = avg; worstP = uczniowie[p.first]; }
    }
    cout << "Najlepsza srednia: " << bestP << " (" << bestA << ")" << endl;
    cout << "Najslabsza srednia: " << worstP << " (" << worstA << ")" << endl;
    return 0;
}
```

